package tsgen

import (
	"fmt"
	"go/constant"
	"go/types"
	"sort"
	"strconv"
	"strings"

	"github.com/faintghost/effectgo/internal/rtshape"
)

// Target is the exact Effect version used to validate generated clients.
const Target = "effect@4.0.4"

// reserved are the names the generated file itself declares.
var reserved = map[string]bool{"Api": true, "TransportError": true, "Schema": true, "SchemaGetter": true,
	"HttpApi": true, "HttpApiGroup": true, "HttpApiEndpoint": true, "HttpApiSchema": true,
	"HttpClientError": true, "BrowserFetchHttpClient": true, "jsonRequest": true, "omitUndefined": true}

// Generate writes the TypeScript file for the results of the packages of one run.
// api is the name given to HttpApi.make, module is the module path and packages
// the analyzed package paths. Every generation error is returned together, sorted,
// each with its position.
func Generate(results []Result, api, module string, packages []string) (string, error) {
	e := &emitter{decls: map[string]Decl{}, classes: map[string]int{}, untagged: map[string]bool{}, usage: map[string]uint8{}}
	var routes []Route
	for _, res := range results {
		for _, d := range res.Decls {
			if _, ok := e.decls[d.Key]; !ok {
				e.decls[d.Key] = d
			}
		}
		routes = append(routes, res.Routes...)
	}
	for _, r := range routes {
		e.usesCookies = e.usesCookies || routeHasCookies(r)
		e.errs = append(e.errs, r.Problems...)
		seen := map[string]bool{}
		for _, er := range r.Errors {
			if seen[er.Key] {
				e.errs = append(e.errs, fmt.Sprintf("%s: the error list of %s lists %s twice; a variant is listed once", r.Pos, r.Name, er.Key))
			}
			seen[er.Key] = true
			if _, exists := e.classes[er.Key]; exists && e.untagged[er.Key] != er.Untagged {
				e.errs = append(e.errs, fmt.Sprintf("error %s is used both as a tagged handler error and an untagged external error; use distinct types", er.Key))
			}
			e.classes[er.Key] = er.Status
			e.untagged[er.Key] = er.Untagged
		}
	}
	e.markUsage(routes)
	e.checkNames()
	groups := e.checkEndpoints(routes)
	order := e.layers()
	if len(e.errs) > 0 {
		return "", e.failure()
	}
	body := e.emitBody(order, groups, api)
	var b strings.Builder
	b.WriteString("// Code generated by effectgo ts. DO NOT EDIT.\n")
	fmt.Fprintf(&b, "// source: module %s; packages: %s\n", module, strings.Join(sortedCopy(packages), ", "))
	fmt.Fprintf(&b, "// target: %s (effect/http-api is unstable in 4.x)\n", Target)
	b.WriteString("\n")
	effectImports := "Schema"
	if e.usesCookies {
		effectImports = "Layer, " + effectImports
	}
	if e.usesJSONPayload {
		effectImports += ", SchemaGetter"
	}
	fmt.Fprintf(&b, "import { %s } from \"effect\"\n", effectImports)
	imports := "HttpApi, HttpApiEndpoint, HttpApiGroup"
	if e.usesNoContent {
		imports += ", HttpApiSchema"
	}
	fmt.Fprintf(&b, "import { %s } from \"effect/http-api\"\n", imports)
	if e.usesCookies {
		b.WriteString(`import { FetchHttpClient } from "effect/http"` + "\n")
	} else {
		b.WriteString(`import type { HttpClientError } from "effect/http"` + "\n")
	}
	if e.usesCookies {
		b.WriteString(`import type { HttpClientError } from "effect/http"` + "\n\n")
	} else {
		b.WriteString("\n")
	}
	if e.usesCookies {
		b.WriteString("// Browser cookies are supplied by the origin's cookie jar; JavaScript cannot set Cookie headers.\n")
		b.WriteString("export const BrowserFetchHttpClient = FetchHttpClient.layer.pipe(\n")
		b.WriteString("  Layer.provide(Layer.succeed(FetchHttpClient.RequestInit, { credentials: \"include\" })),\n")
		b.WriteString(")\n\n")
	}
	if e.usesJSONPayload {
		b.WriteString(jsonRequestBoundary)
	}
	b.WriteString(body)
	return b.String(), nil
}

func routeHasCookies(r Route) bool {
	if r.In == nil {
		return false
	}
	for _, f := range r.In.Root.Fields {
		if f.Cookie != "" {
			return true
		}
	}
	return false
}

// emitter holds the state of one generation.
type emitter struct {
	decls           map[string]Decl  // every named struct, by key
	classes         map[string]int   // the error types of the error lists, by key, with their status
	untagged        map[string]bool  // external wire errors acquire _tag only after decoding
	usage           map[string]uint8 // bit 1: a request type; bit 2: a response type
	errs            []string
	usesNoContent   bool
	usesCookies     bool
	usesJSONPayload bool
}

// checkNames reports the names that two types share, and the names the generator
// writes itself. A type is named in the output when it is an error class or a
// schema constant that is written (the framework's own errors and their fields
// included, through the routes that use them). Enums are written inline and have
// no name, so they cannot collide.
func (e *emitter) checkNames() {
	keys := sortedKeys(e.decls)
	byName := map[string][]Decl{}
	for _, k := range keys {
		if _, isClass := e.classes[k]; !isClass && e.usage[k] == 0 {
			continue // a parameter or query struct, written inline
		}
		d := e.decls[k]
		byName[d.Name] = append(byName[d.Name], d)
	}
	for name, ds := range byName {
		if reserved[name] {
			e.errs = append(e.errs, fmt.Sprintf("type %s (%s) collides with a name the generator writes", name, ds[0].Pos))
		}
		if len(ds) > 1 {
			e.errs = append(e.errs, fmt.Sprintf("two types are named %s: %s (%s) and %s (%s)", name, ds[0].Key, ds[0].Pos, ds[1].Key, ds[1].Pos))
		}
	}
}

// checkEndpoints groups the routes and reports two endpoints with one name in a
// group. It returns the endpoints of each group, by name.
func (e *emitter) checkEndpoints(routes []Route) map[string]map[string]Route {
	groups := map[string]map[string]Route{}
	for _, r := range routes {
		if groups[r.Group] == nil {
			groups[r.Group] = map[string]Route{}
		}
		if prev, ok := groups[r.Group][r.Name]; ok {
			e.errs = append(e.errs, fmt.Sprintf("two endpoints named %s in group %s: %s and %s", r.Name, r.Group, prev.Pos, r.Pos))
			continue
		}
		groups[r.Group][r.Name] = r
	}
	return groups
}

// layers orders the named structs: a type comes after the types it refers to, and
// types of one layer are sorted by name. A cycle is a generation error.
func (e *emitter) layers() []string {
	state := map[string]int{} // 1 visiting, 2 done
	level := map[string]int{}
	var visit func(k string) int
	visit = func(k string) int {
		switch state[k] {
		case 2:
			return level[k]
		case 1:
			d := e.decls[k]
			e.errs = append(e.errs, fmt.Sprintf("recursive type %s is not supported (%s)", d.Name, d.Pos))
			return 0
		}
		state[k] = 1
		lv := 0
		for _, dk := range e.refs(e.decls[k].Type) {
			if _, ok := e.decls[dk]; ok {
				if l := visit(dk) + 1; l > lv {
					lv = l
				}
			}
		}
		state[k] = 2
		level[k] = lv
		return lv
	}
	keys := sortedKeys(e.decls)
	for _, k := range keys {
		visit(k)
	}
	sort.SliceStable(keys, func(i, j int) bool {
		a, b := keys[i], keys[j]
		if level[a] != level[b] {
			return level[a] < level[b]
		}
		return e.decls[a].Name < e.decls[b].Name
	})
	return keys
}

// refs lists the keys of the named structs that the fields of t refer to.
func (e *emitter) refs(t *rtshape.Type) []string {
	var out []string
	var walk func(t *rtshape.Type)
	walk = func(t *rtshape.Type) {
		if t == nil {
			return
		}
		switch t.Cat {
		case rtshape.CatStruct:
			if t.Name != "" {
				out = append(out, t.Key)
				return
			}
			for _, f := range t.Fields {
				walk(f.Type)
			}
		case rtshape.CatSlice, rtshape.CatMap, rtshape.CatPointer:
			walk(t.Elem)
		}
	}
	if t != nil {
		for _, f := range t.Fields {
			walk(f.Type)
		}
	}
	return out
}

// markUsage records whether each named struct is a request type, a response type
// or both. A type used both ways would need two schemas under one name, so that is
// a generation error.
func (e *emitter) markUsage(routes []Route) {
	var mark func(t *rtshape.Type, bit uint8, seen map[string]bool)
	mark = func(t *rtshape.Type, bit uint8, seen map[string]bool) {
		if t == nil {
			return
		}
		if _, _, custom := wire(t, bit&1 != 0); custom {
			return // written as its wire schema; its fields are not on the wire
		}
		if t.Cat == rtshape.CatStruct && t.Name != "" {
			k := t.Key
			e.usage[k] |= bit
			if seen[k] {
				return
			}
			seen[k] = true
		}
		for _, f := range t.Fields {
			mark(f.Type, bit, seen)
		}
		mark(t.Elem, bit, seen)
	}
	for _, r := range routes {
		if r.In != nil && !r.JSONBody {
			if bodyOnly(r.In.Root) {
				mark(r.In.Root, 1, map[string]bool{}) // the payload is this type
			} else {
				for _, f := range r.In.Root.Fields {
					if f.Path == "" && f.Query == "" && f.Header == "" && f.Cookie == "" {
						mark(f.Type, 1, map[string]bool{})
					}
				}
			}
		}
		if r.Out != nil {
			mark(r.Out.Root, 2, map[string]bool{})
		}
		if r.ProxyFailure != nil {
			mark(r.ProxyFailure.Root, 2, map[string]bool{})
		}
		for _, er := range r.Errors {
			if d, ok := e.decls[er.Key]; ok {
				mark(d.Type, 2, map[string]bool{})
			}
		}
	}
	for _, k := range sortedKeys(e.usage) {
		if u := e.usage[k]; u == 3 {
			d := e.decls[k]
			e.errs = append(e.errs, fmt.Sprintf("type %s is both a request and a response type (%s); the schemas differ, split it", d.Name, d.Pos))
		}
	}
}

// bodyOnly reports whether every field of an input is a body field.
func bodyOnly(t *rtshape.Type) bool {
	for _, f := range t.Fields {
		if f.Path != "" || f.Query != "" || f.Header != "" || f.Cookie != "" {
			return false
		}
	}
	return true
}

// failure joins the generation errors: sorted and without repeats.
func (e *emitter) failure() error {
	sort.Strings(e.errs)
	var out []string
	for i, s := range e.errs {
		if i == 0 || s != e.errs[i-1] {
			out = append(out, s)
		}
	}
	return fmt.Errorf("%s", strings.Join(out, "\n"))
}

// emitBody writes the declarations, the transport error type and the API.
func (e *emitter) emitBody(order []string, groups map[string]map[string]Route, api string) string {
	var b strings.Builder
	for _, k := range order {
		d := e.decls[k]
		if status, ok := e.classes[k]; ok {
			e.class(&b, d, status)
			continue
		}
		if e.usage[k] == 0 {
			continue // only a parameter or query struct, written inline
		}
		if _, _, custom := wire(d.Type, e.usage[k]&1 != 0); custom {
			continue // every use is written as its wire schema (see wire)
		}
		e.schemaConst(&b, d)
	}
	b.WriteString("export type TransportError = HttpClientError.HttpClientError | Schema.SchemaError\n\n")
	b.WriteString("export const Api = HttpApi.make(" + strconv.Quote(api) + ").add(\n")
	var names []string
	for g := range groups {
		names = append(names, g)
	}
	sort.Strings(names)
	for _, g := range names {
		fmt.Fprintf(&b, "  HttpApiGroup.make(%s).add(\n", strconv.Quote(g))
		var eps []string
		for n := range groups[g] {
			eps = append(eps, n)
		}
		sort.Strings(eps)
		for _, n := range eps {
			e.endpoint(&b, groups[g][n])
		}
		b.WriteString("  ),\n")
	}
	b.WriteString(")\n")
	return b.String()
}

// schemaConst writes a struct as a Schema.Struct constant, in the direction it is used.
func (e *emitter) schemaConst(b *strings.Builder, d Decl) {
	req := e.usage[d.Key]&1 != 0
	fmt.Fprintf(b, "export const %s = Schema.Struct({\n", d.Name)
	for _, l := range e.fieldLines(d.Type.Fields, req, req, "  ") {
		b.WriteString(l + "\n")
	}
	b.WriteString("})\n\n")
}

// class writes an error type as a tagged error with its status.
func (e *emitter) class(b *strings.Builder, d Decl, status int) {
	lines := e.fieldLines(d.Type.Fields, false, false, "    ")
	if _, c, custom := wire(d.Type, false); custom {
		// The body is the type's own encoding, so no field is checked.
		b.WriteString(c + "\n")
		lines = nil
	}
	if e.untagged[d.Key] {
		fmt.Fprintf(b, "export class %s extends Schema.Error<%s>(%s)(\n", d.Name, d.Name, strconv.Quote(d.Name))
		b.WriteString("  {\n")
		for _, l := range lines {
			b.WriteString(l + "\n")
		}
		fmt.Fprintf(b, "  },\n  { httpApiStatus: %d },\n) {\n  readonly _tag = %s\n}\n\n", status, strconv.Quote(d.Name))
		return
	}
	fmt.Fprintf(b, "export class %s extends Schema.TaggedError<%s>()(\n", d.Name, d.Name)
	fmt.Fprintf(b, "  %s,\n", strconv.Quote(d.Name))
	if len(lines) == 0 {
		b.WriteString("  {},\n")
	} else {
		b.WriteString("  {\n")
		for _, l := range lines {
			b.WriteString(l + "\n")
		}
		b.WriteString("  },\n")
	}
	fmt.Fprintf(b, "  { httpApiStatus: %d },\n) {}\n\n", status)
}

// endpoint writes one endpoint of a group.
func (e *emitter) endpoint(b *strings.Builder, r Route) {
	var params, query, headers, body []*rtshape.Field
	if r.In != nil {
		for _, f := range r.In.Root.Fields {
			switch {
			case f.Path != "":
				params = append(params, f)
			case f.Query != "":
				query = append(query, f)
			case f.Header != "", f.Cookie != "":
				headers = append(headers, f)
			default:
				body = append(body, f)
			}
		}
	}
	var opts []string
	clientHeaders := headerFields(headers)
	clientParts := len(params) + len(query) + len(clientHeaders)
	if len(params) > 0 {
		opts = append(opts, "      params: {")
		opts = append(opts, e.fieldLines(urlFields(params), true, false, "        ")...)
		opts = append(opts, "      },")
	}
	if len(query) > 0 {
		opts = append(opts, "      query: Schema.Struct({")
		opts = append(opts, e.fieldLines(urlFields(query), true, false, "        ")...)
		opts = append(opts, "      }),")
	}
	if len(clientHeaders) > 0 {
		opts = append(opts, "      headers: Schema.Struct({")
		opts = append(opts, e.fieldLines(clientHeaders, true, false, "        ")...)
		opts = append(opts, "      }),")
	}
	if len(body) > 0 || r.JSONBody && r.In != nil && r.In.Root.UnmarshalJSON {
		if len(body) > 0 && body[0].Form != "" {
			e.usesNoContent = true // HttpApiSchema also owns the multipart encoding annotation.
			opts = append(opts, "      payload: Schema.Struct({")
			opts = append(opts, e.fieldLines(body, true, true, "        ")...)
			opts = append(opts, "      }).pipe(HttpApiSchema.asMultipart()),")
		} else if r.JSONBody {
			e.usesJSONPayload = true
			payload := e.jsonPayload(r.In.Root, body)
			if _, comment, custom := wire(r.In.Root, true); custom {
				opts = append(opts, "      "+comment)
			}
			if r.JSONBodyEmpty {
				payload = "Schema.UndefinedOr(" + payload + ")"
			}
			opts = append(opts, "      payload: jsonRequest("+payload+"),")
		} else if _, c, custom := wire(r.In.Root, true); custom && clientParts == 0 {
			e.usesJSONPayload = true
			opts = append(opts, "      "+c)
			opts = append(opts, "      payload: jsonRequest(Schema.Unknown),")
		} else if clientParts == 0 && r.In.Root.Name != "" {
			e.usesJSONPayload = true
			opts = append(opts, "      payload: jsonRequest("+r.In.Root.Name+"),")
		} else {
			e.usesJSONPayload = true
			opts = append(opts, "      payload: jsonRequest(Schema.Struct({")
			opts = append(opts, e.fieldLines(body, true, true, "        ")...)
			opts = append(opts, "      })),")
		}
	}
	success := "HttpApiSchema.NoContent"
	if r.NoContent {
		e.usesNoContent = true
	} else if r.Binary {
		e.usesNoContent = true
		success = "Schema.Uint8Array.pipe(HttpApiSchema.asUint8Array())"
	} else if r.Redirect {
		e.usesNoContent = true
		success = `Schema.String.pipe(HttpApiSchema.asText({ contentType: "text/html" }))`
	} else {
		success = e.expr(r.Out.Root, false)
		if c := wireComment(r.Out.Root, false); c != "" {
			opts = append(opts, "      "+c)
		}
	}
	statuses := r.SuccessStatuses
	if len(statuses) == 0 {
		statuses = []int{r.SuccessStatus}
	}
	var successes []string
	for _, status := range statuses {
		schema := success
		if status == 204 || status == 205 || status == 304 {
			e.usesNoContent = true
			if status == 204 {
				schema = "HttpApiSchema.NoContent"
			} else {
				schema = fmt.Sprintf("HttpApiSchema.Empty(%d)", status)
			}
		} else if status != 0 && status != 200 {
			e.usesNoContent = true
			schema += fmt.Sprintf(".pipe(HttpApiSchema.status(%d))", status)
		}
		successes = append(successes, schema)
	}
	if len(successes) == 1 {
		success = successes[0]
	} else {
		success = "[" + strings.Join(successes, ", ") + "]"
	}
	opts = append(opts, "      success: "+success+",")
	var errs []string
	for _, er := range r.Errors {
		errs = append(errs, er.Name)
	}
	opts = append(opts, "      error: ["+strings.Join(errs, ", ")+"],")
	ctor := "HttpApiEndpoint." + strings.ToLower(r.Method)
	head := fmt.Sprintf("    %s(%s, %s, {", ctor, strconv.Quote(r.Name), strconv.Quote(tsPath(r.Pattern)))
	if r.Method == "DELETE" {
		head = fmt.Sprintf("    HttpApiEndpoint.make(\"DELETE\")(%s, %s, {", strconv.Quote(r.Name), strconv.Quote(tsPath(r.Pattern)))
	}
	b.WriteString(head + "\n")
	for _, o := range opts {
		b.WriteString(o + "\n")
	}
	b.WriteString("    }),\n")
}

// urlFields returns copies of path or query fields keyed by their URL name. Effect
// fills a path parameter `:name` from the params key `name`, and rt reads the
// query value of the tag name, so the key is the tag, not the json name.
func urlFields(fields []*rtshape.Field) []*rtshape.Field {
	out := make([]*rtshape.Field, 0, len(fields))
	for _, f := range fields {
		c := *f
		if c.Path != "" {
			c.JSON = c.Path
		} else {
			c.JSON = c.Query
		}
		out = append(out, &c)
	}
	return out
}

// headerFields returns copies keyed by HTTP header names. Cookie fields are
// supplied by the browser's cookie jar and therefore do not become request
// headers, which JavaScript is forbidden to set.
func headerFields(fields []*rtshape.Field) []*rtshape.Field {
	out := make([]*rtshape.Field, 0, len(fields))
	for _, f := range fields {
		if f.Cookie != "" {
			continue
		}
		c := *f
		c.JSON = c.Header
		out = append(out, &c)
	}
	return out
}

// tsPath turns a Go pattern into an Effect path: {id} is :id.
func tsPath(pattern string) string {
	segs := strings.Split(pattern, "/")
	for i, s := range segs {
		if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
			segs[i] = ":" + s[1:len(s)-1]
		}
	}
	return strings.Join(segs, "/")
}

// fieldLines writes the fields of an object. req is the request direction (Go
// decodes the value); body is true when the fields are body fields, which get
// their checks. Outside the request direction a field has no rule output.
func (e *emitter) fieldLines(fields []*rtshape.Field, req, body bool, indent string) []string {
	var out []string
	for _, f := range fields {
		checks, comments := "", []string(nil)
		if req {
			checks, comments = ruleOutput(f, body)
		}
		if is64(f.Type) {
			out = append(out, indent+"// server: 64-bit integer; values beyond 2^53 lose precision in JavaScript")
		}
		if c := wireComment(f.Type, req); c != "" {
			out = append(out, indent+c)
		}
		for _, c := range comments {
			out = append(out, indent+c)
		}
		out = append(out, indent+key(f.JSON)+": "+e.fieldExpr(f, req, checks)+",")
	}
	return out
}

// fieldExpr is the schema of a field, with its checks on the base type.
func (e *emitter) fieldExpr(f *rtshape.Field, req bool, checks string) string {
	if f.Form != "" {
		base := "Schema.File"
		if !f.File {
			base = e.expr(f.Type, true) + checks
		}
		if f.Optional {
			return "Schema.optionalKey(" + base + ")"
		}
		return base
	}
	base := e.expr(f.Type, req) + checks
	if !req && f.JSONString {
		if _, _, custom := wire(f.Type, false); !custom {
			switch f.Type.Cat {
			case rtshape.CatString, rtshape.CatInt, rtshape.CatFloat, rtshape.CatBool, rtshape.CatEnum:
				base = "Schema.String"
			}
		}
	}
	if !req && f.OmitParent {
		if f.Optional && !f.Omitempty {
			base = "Schema.NullOr(" + base + ")"
		}
		return "Schema.optionalKey(" + base + ")"
	}
	switch {
	case f.Optional && req:
		return "Schema.optionalKey(Schema.NullOr(" + base + "))"
	case f.Optional && f.Omitempty:
		return "Schema.optionalKey(" + base + ")"
	case f.Optional:
		return "Schema.NullOr(" + base + ")"
	case !req && f.Omitempty:
		return "Schema.optionalKey(" + base + ")"
	}
	return base
}

// expr is the schema of a type. In the request direction a slice or map is not
// null (Go decodes what the client sends); in the response direction a nil slice
// or map encodes as null.
func (e *emitter) expr(t *rtshape.Type, req bool) string {
	if s, _, ok := wire(t, req); ok {
		return s
	}
	switch t.Cat {
	case rtshape.CatString, rtshape.CatTime:
		return "Schema.String"
	case rtshape.CatInt:
		if is64(t) {
			return `Schema.Number.check(Schema.makeFilter(globalThis.Number.isInteger, { expected: "an integer" }))`
		}
		return "Schema.Int"
	case rtshape.CatFloat:
		return "Schema.Number"
	case rtshape.CatBool:
		return "Schema.Boolean"
	case rtshape.CatEnum:
		var lits []string
		for _, c := range t.Consts {
			if c.Val().Kind() == constant.String {
				lits = append(lits, strconv.Quote(constant.StringVal(c.Val())))
			} else {
				lits = append(lits, c.Val().ExactString())
			}
		}
		return "Schema.Literals([" + strings.Join(lits, ", ") + "])"
	case rtshape.CatStruct:
		if t.Name != "" {
			return t.Name
		}
		return "Schema.Struct({\n" + strings.Join(e.fieldLines(t.Fields, req, req, "  "), "\n") + "\n})"
	case rtshape.CatSlice:
		s := "Schema.Array(" + e.expr(t.Elem, req) + ")"
		if req {
			return s
		}
		return "Schema.NullOr(" + s + ")"
	case rtshape.CatMap:
		s := "Schema.Record(Schema.String, " + e.expr(t.Elem, req) + ")"
		if req {
			return s
		}
		return "Schema.NullOr(" + s + ")"
	case rtshape.CatPointer:
		return "Schema.NullOr(" + e.expr(t.Elem, req) + ")"
	case rtshape.CatRaw, rtshape.CatAny:
		return "Schema.Unknown"
	}
	return "Schema.Unknown"
}

// wire is the schema of a named type whose JSON form its own methods set, in one
// direction, and the comment that says so. The response is written by
// MarshalJSON, or by MarshalText as a JSON string; a request is read by
// UnmarshalJSON. The generator cannot see what those methods write or read, so
// the schema is Schema.Unknown, or Schema.String for MarshalText: it is never
// stricter than the server. MarshalText counts for the response only, because
// rt/schema decodes a request by its Go kind and never calls UnmarshalText.
func wire(t *rtshape.Type, req bool) (schema, comment string, ok bool) {
	if t.Name == "" {
		return "", "", false
	}
	switch {
	case !req && t.MarshalJSON:
		return "Schema.Unknown", "// server: custom JSON encoding (MarshalJSON); shape not checked", true
	case req && t.UnmarshalJSON:
		return "Schema.Unknown", "// server: custom JSON decoding (UnmarshalJSON); shape not checked", true
	case !req && t.MarshalText:
		return "Schema.String", "// server: text encoding (MarshalText); the JSON value is a string", true
	}
	return "", "", false
}

// wireComment is the comment of the first type in t, through its pointers, slices
// and maps, whose schema wire sets; "" when there is none.
func wireComment(t *rtshape.Type, req bool) string {
	if _, c, ok := wire(t, req); ok {
		return c
	}
	switch t.Cat {
	case rtshape.CatPointer, rtshape.CatSlice, rtshape.CatMap:
		return wireComment(t.Elem, req)
	}
	return ""
}

// ruleOutput returns the checks of a body field in the request direction and the
// comment lines for the rules that have no TypeScript check. A check is exact
// (the same condition as rt); a comment states what the server checks.
func ruleOutput(f *rtshape.Field, body bool) (string, []string) {
	var checks string
	var comments []string
	cat := f.Type.RuleCat
	number := cat == "int" || cat == "uint" || cat == "float"
	for _, r := range f.Rules {
		switch r.Name {
		case "trim":
		case "min", "max":
			switch {
			case body && number && r.Name == "min":
				checks += ".check(Schema.isGreaterThanOrEqualTo(" + r.Arg + "))"
			case body && number:
				checks += ".check(Schema.isLessThanOrEqualTo(" + r.Arg + "))"
			case body && cat == "slice" && r.Name == "min":
				checks += ".check(Schema.isMinLength(" + r.Arg + "))"
			case body && cat == "slice":
				checks += ".check(Schema.isMaxLength(" + r.Arg + "))"
			case cat == "string":
				comments = append(comments, "// server: "+r.Name+" "+r.Arg+" runes")
			case cat == "slice" || cat == "map":
				comments = append(comments, "// server: "+r.Name+" "+r.Arg+" items")
			default:
				comments = append(comments, "// server: "+r.Name+" "+r.Arg)
			}
		case "nonempty":
			if body && cat == "slice" {
				checks += ".check(Schema.isMinLength(1))"
			} else {
				comments = append(comments, "// server: nonempty")
			}
		case "singleline":
			if body && cat == "string" {
				checks += `.check(Schema.isPattern(/^[^\r\n]*$/))`
			} else {
				comments = append(comments, "// server: single line")
			}
		case "email":
			comments = append(comments, "// server: email address (a bare address, no display name)")
		case "pattern":
			comments = append(comments, "// server: pattern "+r.Arg+" (checked by the server only)")
		}
	}
	return checks, comments
}

// is64 reports whether a field's type is a 64-bit integer (int, uint and the
// 64-bit kinds).
func is64(t *rtshape.Type) bool {
	if t.Cat != rtshape.CatInt {
		return false
	}
	b, ok := t.Go.Underlying().(*types.Basic)
	if !ok {
		return false
	}
	switch b.Kind() {
	case types.Int, types.Int64, types.Uint, types.Uint64:
		return true
	}
	return false
}

// key writes a JSON name as a TypeScript property key.
func key(name string) string {
	for i, c := range name {
		ok := c == '_' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || i > 0 && c >= '0' && c <= '9'
		if !ok {
			return strconv.Quote(name)
		}
	}
	if name == "" {
		return `""`
	}
	return name
}

func sortedKeys[V any](m map[string]V) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func sortedCopy(s []string) []string {
	out := append([]string(nil), s...)
	sort.Strings(out)
	return out
}
